exercises.solutionCode:
#include <stdint.h>
#include <stddef.h>

int pwm_pulse_from_percent(uint32_t period_ticks, unsigned int percent, uint32_t *pulse)
{
    uint64_t scaled;

    if (pulse == NULL || period_ticks == 0u || percent > 100u) {
        return -1;
    }

    /* 先扩宽到 64 位再乘，避免 period_ticks 较大时 32 位乘法溢出 */
    scaled = (uint64_t)period_ticks * (uint64_t)percent;

    /* 加半个除数实现四舍五入 */
    *pulse = (uint32_t)((scaled + 50u) / 100u);
    return 0;
}
